from taf.ul.ettf.logger import custom_logger


logger = custom_logger('ettf.main_context')


class TestData(object):
    def __init__(self):
        self.suite_name = 'default_suite_name'
        self.test_name = 'default_test_name'


class Context(object):
    def __init__(self):
        self._simulator = None
        self._test_data = TestData()

    def change_simulator(self, simulator):
        logger.debug('Simulator has changed to {}'.format(simulator))
        self._simulator = simulator

    def set_suite_name(self, name):
        logger.debug('{} suite started'.format(name))
        self._test_data.suite_name = name

    def set_test_name(self, name):
        logger.debug('{} test started'.format(name))
        self._test_data.test_name = name

    @property
    def simulator(self):
        return self._simulator

    @property
    def suite_name(self):
        return self._test_data.suite_name

    @property
    def test_name(self):
        return self._test_data.test_name
